SELECT 
  COUNT(*) AS total_products_in_db,
  COUNT(*) FILTER (WHERE barcode IS NOT NULL) AS products_with_sku,
  COUNT(*) FILTER (WHERE stock_quantity > 0) AS in_stock_products
FROM public.products;
